script:
const key = ctx.params.tieu_de_chua || ctx.testPrefix;

await step('Tìm thư cần gắn sao trong Hộp thư đến', async () => {
  await page.locator('tbody tr .mail-content__subject', { hasText: key }).first().waitFor({ timeout: 30000 });
});

const row = () => page.locator('tbody tr').filter({ has: page.locator('.mail-content__subject', { hasText: key }) }).first();
const star = () => row().locator('.hrv-next-input-checkbox-star');
// Sao đã gắn thì biểu tượng có màu #F0AD4F
const isStarred = async () => (await star().locator('path').evaluateAll(ps => ps.some(p => /F0AD4F/i.test(p.getAttribute('fill') || ''))));
const waitStar = async want => {
  for (let i = 0; i < 20; i++) { if ((await isStarred()) === want) return; await page.waitForTimeout(500); }
  throw new Error(want ? 'Thư không được gắn sao' : 'Thư không được bỏ sao');
};

await step('Đưa thư về trạng thái chưa gắn sao', async () => {
  if (await isStarred()) { await star().click(); await waitStar(false); }
});

await step('Gắn sao', async () => {
  await star().click();
  await waitStar(true);
});

await step('Bỏ sao', async () => {
  await star().click();
  await waitStar(false);
});
